using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;

internal sealed class NetChatClient {
    readonly Uri root;readonly string cookie,bearer;
    internal NetChatClient(Uri master,OgbgIdentity identity){if(master.Port>=65535)throw new ArgumentException("Master port has no adjacent chat port.");root=new UriBuilder(master){Port=master.Port+1,Path="/",Query="",Fragment=""}.Uri;cookie=identity.CookieHeader??"";bearer=identity.BearerToken??"";}
    internal IDictionary<string,object> Request(string action,long after,string text){var json=new JavaScriptSerializer{MaxJsonLength=262144};var body=Encoding.UTF8.GetBytes(json.Serialize(new{cookie=cookie,bearer=bearer,after=after,text=text??""}));var request=(HttpWebRequest)WebRequest.Create(new Uri(root,"chat/"+action));request.Method="POST";request.ContentType="application/json";request.Timeout=7000;request.ReadWriteTimeout=7000;request.AllowAutoRedirect=false;request.ContentLength=body.Length;using(var output=request.GetRequestStream())output.Write(body,0,body.Length);using(var response=request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream(),Encoding.UTF8)){char[] buffer=new char[262145];int n=reader.ReadBlock(buffer,0,buffer.Length);if(n>262144)throw new InvalidDataException("Chat response is too large.");return json.DeserializeObject(new string(buffer,0,n)) as IDictionary<string,object>;}}
}
internal sealed partial class LauncherForm {
    int _chatPolling,_chatGeneration=-1;long _chatCursor;string _chatEpoch="";bool _netChatConnected;DateTime _nextChatPoll=DateTime.MinValue,_nextChatError=DateTime.MinValue;
    void NetChatTick(){if(!_netMode||_onlineIdentity==null||(_dedicatedServer&&_lobbyServer!=null))return;if(_chatGeneration!=_netGeneration){_chatGeneration=_netGeneration;_chatCursor=0;_chatEpoch="";_netChatConnected=false;_onlineNames=new string[0];_globalHistory.Clear();_nextChatPoll=DateTime.MinValue;}if(DateTime.UtcNow<_nextChatPoll||Interlocked.CompareExchange(ref _chatPolling,1,0)!=0)return;_nextChatPoll=DateTime.UtcNow.AddSeconds(2);int generation=_netGeneration;long cursor=_chatCursor;OgbgIdentity identity=_onlineIdentity;Uri master;try{master=NetDirectoryAddress();}catch{Interlocked.Exchange(ref _chatPolling,0);return;}
        ThreadPool.QueueUserWorkItem(delegate{try{var result=new NetChatClient(master,identity).Request("poll",cursor,null);LanUi(delegate{if(!_netMode||generation!=_netGeneration||result==null)return;object value;object epochValue;string epoch=result.TryGetValue("epoch",out epochValue)?Convert.ToString(epochValue):"";if(_chatEpoch.Length>0&&epoch!=_chatEpoch){_chatCursor=0;_chatEpoch=epoch;_globalHistory.Clear();_nextChatPoll=DateTime.MinValue;_netChatConnected=true;NativePublish();return;}_chatEpoch=epoch;long latest=0;if(result.TryGetValue("latest",out value))Int64.TryParse(Convert.ToString(value),out latest);if(latest<cursor){_chatCursor=0;_globalHistory.Clear();_nextChatPoll=DateTime.MinValue;}else{if(result.TryGetValue("messages",out value)){var array=value as object[];if(array!=null)foreach(var item in array){var m=item as IDictionary<string,object>;object name,text;if(m!=null&&m.TryGetValue("name",out name)&&m.TryGetValue("text",out text))AddChat(false,Convert.ToString(name)+": "+Convert.ToString(text));}}_chatCursor=latest;}if(result.TryGetValue("online",out value)){var array=value as object[];var names=new List<string>();if(array!=null)foreach(var x in array)names.Add(Convert.ToString(x));_onlineNames=names.ToArray();RefreshPlayers();}_netChatConnected=true;NativePublish();});}catch(Exception){LanUi(delegate{if(generation!=_netGeneration)return;_netChatConnected=false;_onlineNames=new string[0];if(DateTime.UtcNow>=_nextChatError){_nextChatError=DateTime.UtcNow.AddSeconds(30);AppendLog("CHAT: server unavailable or account verification failed.");}NativePublish();});}finally{Interlocked.Exchange(ref _chatPolling,0);}});
    }
    void SendNetChat(string text){if(!_netChatConnected||_onlineIdentity==null)throw new InvalidOperationException("Chat Server is not connected.");var identity=_onlineIdentity;var master=NetDirectoryAddress();int generation=_netGeneration;ThreadPool.QueueUserWorkItem(delegate{try{new NetChatClient(master,identity).Request("send",0,text);LanUi(delegate{if(generation==_netGeneration)_nextChatPoll=DateTime.MinValue;});}catch(Exception){LanUi(delegate{if(generation==_netGeneration)LanError("Chat message could not be sent.");});}});}
}
